using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class ExecutiveDashboardPage:UserControl{public ExecutiveDashboardPage(){if(!AppSession.Can("Dashboard.View")){Controls.Add(Ui.Label(L.Fa?"دسترسی ندارید":"Access denied",16,true));return;}Dock=DockStyle.Fill;AutoScroll=true;var root=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,WrapContents=true};Metric(root,L.Fa?"فرصت‌های باز":"Open jobs",Database.Scalar("SELECT COUNT(*) FROM Jobs WHERE Status='Open'"));Metric(root,L.Fa?"کاندیداها":"Candidates",Database.Scalar("SELECT COUNT(*) FROM Candidates"));Metric(root,L.Fa?"در مصاحبه":"In interview",Database.Scalar("SELECT COUNT(*) FROM Applications WHERE Stage='Interview'"));Metric(root,L.Fa?"پیشنهادها":"Offers",Database.Scalar("SELECT COUNT(*) FROM Offers"));Metric(root,L.Fa?"استخدام شده":"Hired",Database.Scalar("SELECT COUNT(*) FROM Applications WHERE Stage='Hired'"));Metric(root,L.Fa?"میانگین امتیاز":"Avg score",Database.Scalar("SELECT CAST(AVG(CAST(Score AS decimal(10,1))) AS decimal(10,1)) FROM Applications WHERE Score IS NOT NULL"));var grid=Ui.Grid();grid.Width=1000;grid.Height=340;grid.DataSource=Database.Query("SELECT TOP 20 c.FullName Candidate,j.Title Job,a.Stage,a.Score,a.AppliedAt FROM Applications a JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId ORDER BY a.AppliedAt DESC");root.Controls.Add(grid);Controls.Add(root);}void Metric(FlowLayoutPanel p,string title,object value){var c=Ui.Card();c.Width=245;c.Height=105;var t=Ui.Label(title,10);t.Location=new Point(15,15);var v=Ui.Label(value==null||value==DBNull.Value?"0":Convert.ToString(value),22,true);v.Location=new Point(15,48);c.Controls.Add(t);c.Controls.Add(v);p.Controls.Add(c);}}}
